// Package ciworkflowmanagement contains the narrow, create-only repository
// filesystem boundary for the CI workflow generated by the preview service.
//
// A management operation never accepts a path or workflow from the browser.
// The only writable path is the fixed .github/workflows/roborev.yml target,
// and the only bytes accepted by Create are the server-held preview bytes.
package ciworkflowmanagement

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
	"unicode/utf8"

	"github.com/froze/roborev-dashboard/internal/pathsafety"
)

const (
	WorkflowTarget       = ".github/workflows/roborev.yml"
	MaxBytes       int64 = 256 << 10
	directoryMode        = 0o755
	fileMode             = 0o644
)

// File is the handle used for the create-only mutation. It deliberately
// combines the read-side identity contract with the small write surface. An
// implementation must report identity for this same open handle; callers
// never reopen a path to establish the identity of a write.
type File interface {
	io.Writer
	Sync() error
	Stat() (os.FileInfo, error)
	Identity() (string, error)
	Close() error
}

// FileSystem is the complete injected mutation boundary. Mkdir creates one
// path component only. CreateExclusive must have no-replace semantics (the OS
// implementation uses O_WRONLY|O_CREATE|O_EXCL).
type FileSystem interface {
	pathsafety.FileSystem
	Mkdir(string, os.FileMode) error
	CreateExclusive(string, os.FileMode) (File, error)
}

type osFileSystem struct{}
type osFile struct{ *os.File }

// OSFileSystem is the production implementation. Tests should inject a
// deterministic implementation instead of touching a real repository.
type OSFileSystem = osFileSystem

func (osFileSystem) Lstat(path string) (os.FileInfo, error) { return os.Lstat(path) }
func (osFileSystem) Open(path string) (pathsafety.File, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	return &osReadFile{File: f}, nil
}
func (osFileSystem) EvalSymlinks(path string) (string, error) { return filepath.EvalSymlinks(path) }
func (osFileSystem) Identity(path string, info os.FileInfo) (string, error) {
	return pathsafety.FileIdentity(path, info)
}
func (osFileSystem) IsReparse(path string, info os.FileInfo) bool {
	return pathsafety.IsReparsePoint(path, info)
}
func (osFileSystem) Mkdir(path string, mode os.FileMode) error { return os.Mkdir(path, mode) }
func (osFileSystem) CreateExclusive(path string, mode os.FileMode) (File, error) {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return nil, err
	}
	return &osFile{File: f}, nil
}

type osReadFile struct{ *os.File }

func (f *osReadFile) Identity() (string, error) { return pathsafety.HandleIdentity(f.File) }

func (f *osFile) Identity() (string, error) { return pathsafety.HandleIdentity(f.File) }

// TargetStatus is intentionally a small allowlist suitable for a browser DTO.
type TargetStatus string

const (
	TargetAbsentSafe TargetStatus = "absent-safe"
	TargetExists     TargetStatus = "exists"
	TargetUnsafe     TargetStatus = "unsafe"
)

// NodeStatus records the state of one of the two fixed directory components.
// It is retained in Plan but is not itself a browser-facing filesystem path.
type NodeStatus uint8

const (
	nodeAbsent NodeStatus = iota
	nodePresent
	nodeUnsafe
)

type directoryPlan struct {
	path     string
	status   NodeStatus
	snapshot pathsafety.Snapshot
}

type targetPlan struct {
	path     string
	status   TargetStatus
	snapshot pathsafety.Snapshot
}

// Plan is an identity-bound, pre-mutation plan. Its path and snapshots are
// deliberately private so an HTTP layer cannot accidentally serialize actual
// repository paths. Use Status and Target for sanitized information.
type Plan struct {
	root      string
	rootSnap  pathsafety.Snapshot
	github    directoryPlan
	workflows directoryPlan
	target    targetPlan
}

// Status returns the fixed target's create-only eligibility.
func (p Plan) Status() TargetStatus { return p.target.status }

// Target returns the only browser-visible target string.
func (p Plan) Target() string { return WorkflowTarget }

// WriteAvailable reports whether this plan can be used for a create operation.
func (p Plan) WriteAvailable() bool { return p.target.status == TargetAbsentSafe }

// Valid reports whether a plan has a canonical root and a create-only target.
func (p Plan) Valid() bool {
	return p.root != "" && p.rootSnap.Exists && p.rootSnap.Kind == pathsafety.Directory && p.target.status == TargetAbsentSafe
}

// ReasonCode and WarningCode are internal-safe allowlists. They intentionally
// never include the wrapped filesystem error, path, binary, or repository.
type ReasonCode string
type WarningCode string

const (
	ReasonInvalidPlan         ReasonCode = "invalid-plan"
	ReasonInvalidContent      ReasonCode = "invalid-content"
	ReasonCanceled            ReasonCode = "canceled"
	ReasonStale               ReasonCode = "stale"
	ReasonUnsafe              ReasonCode = "unsafe"
	ReasonTargetExists        ReasonCode = "target-exists"
	ReasonDirectoryCreate     ReasonCode = "directory-create-failed"
	ReasonCreate              ReasonCode = "create-failed"
	ReasonWrite               ReasonCode = "write-failed"
	ReasonSync                ReasonCode = "sync-failed"
	ReasonHandleStat          ReasonCode = "handle-stat-failed"
	ReasonHandleIdentity      ReasonCode = "handle-identity-failed"
	ReasonClose               ReasonCode = "close-failed"
	ReasonReadback            ReasonCode = "readback-failed"
	ReasonReadbackMismatch    ReasonCode = "readback-mismatch"
	ReasonReadbackReplacement ReasonCode = "readback-replaced"
	ReasonRepositoryDrift     ReasonCode = "repository-drift"
	ReasonParentDrift         ReasonCode = "parent-drift"
	ReasonZeroProgress        ReasonCode = "zero-progress"

	WarningWrite    WarningCode = "write-error"
	WarningSync     WarningCode = "sync-error"
	WarningStat     WarningCode = "handle-stat-error"
	WarningIdentity WarningCode = "handle-identity-error"
	WarningClose    WarningCode = "close-error"
)

// ResultStatus distinguishes cancellation/staleness before mutation from the
// honest post-mutation states. Once mutation starts, cancellation cannot turn
// a result into a pre-mutation cancellation.
type ResultStatus string

const (
	StatusPreMutationStale    ResultStatus = "pre-mutation-stale"
	StatusPreMutationCanceled ResultStatus = "pre-mutation-canceled"
	StatusVerifiedCreated     ResultStatus = "verified-created"
	StatusFailedUnverified    ResultStatus = "failed-unverified"
)

// Receipt is an opaque server-side verification capability. Its fields are
// private by design: callers can pass it to VerifyCreated after a slow
// read-only Git inspection, but cannot turn it into a path-bearing DTO.
type Receipt struct {
	rootPath       string
	parentPath     string
	targetPath     string
	rootIdentity   string
	parentIdentity string
	fileIdentity   string
	content        []byte
	digest         string
}

// Result is safe to map to a public DTO after sanitizing Status, Reason and
// Warning. Receipt is server-side only and should never be JSON encoded.
type Result struct {
	Status  ResultStatus
	Reason  ReasonCode
	Warning WarningCode
	Receipt *Receipt
}

// Service implements the create-only operation over an injected filesystem.
type Service struct{ FS FileSystem }

func New(fs FileSystem) *Service {
	if fs == nil {
		fs = osFileSystem{}
	}
	return &Service{FS: fs}
}

// NewService is retained as an explicit constructor name for callers whose
// other adapters use the Service suffix.
func NewService(fs FileSystem) *Service { return New(fs) }

// Plan captures the canonical root and every fixed path state. Target
// failures are classified as unsafe so preview callers can still show the
// YAML with a disabled create action; root failures return a sanitized error.
func (s *Service) Plan(ctx context.Context, rawRoot string) (Plan, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return Plan{}, err
	}
	if s == nil || s.FS == nil {
		return Plan{}, ErrUnavailable
	}
	root, err := pathsafety.CanonicalAbsolutePath(s.FS, rawRoot)
	if err != nil {
		return Plan{}, ErrInvalidRoot
	}
	rootSnap, err := pathsafety.CaptureDirectory(s.FS, root)
	if err != nil || !rootSnap.Exists || !within(root, rootSnap.Path) {
		return Plan{}, ErrInvalidRoot
	}
	githubPath := filepath.Join(root, ".github")
	workflowsPath := filepath.Join(githubPath, "workflows")
	targetPath := filepath.Join(workflowsPath, "roborev.yml")
	if !within(root, githubPath) || !within(root, workflowsPath) || !within(root, targetPath) || filepath.Clean(targetPath) != filepath.Join(root, ".github", "workflows", "roborev.yml") {
		return Plan{}, ErrInvalidRoot
	}
	github := captureDirectoryPlan(s.FS, githubPath)
	workflows := captureDirectoryPlan(s.FS, workflowsPath)
	target := captureTargetPlan(s.FS, targetPath, github.status, workflows.status)
	return Plan{root: root, rootSnap: rootSnap, github: github, workflows: workflows, target: target}, nil
}

// Inspect is an alias emphasizing that this operation is read-only.
func (s *Service) Inspect(ctx context.Context, rawRoot string) (Plan, error) {
	return s.Plan(ctx, rawRoot)
}

var (
	ErrUnavailable  = errors.New("CI workflow management is unavailable")
	ErrInvalidRoot  = errors.New("CI workflow management repository root is invalid")
	errZeroProgress = errors.New("zero write progress")
)

func captureDirectoryPlan(fs FileSystem, path string) directoryPlan {
	snapshot, err := pathsafety.CapturePlannedDirectory(fs, path)
	if err != nil {
		return directoryPlan{path: path, status: nodeUnsafe}
	}
	if snapshot.Exists {
		return directoryPlan{path: path, status: nodePresent, snapshot: snapshot}
	}
	return directoryPlan{path: path, status: nodeAbsent, snapshot: snapshot}
}

func captureTargetPlan(fs FileSystem, path string, github, workflows NodeStatus) targetPlan {
	target := targetPlan{path: path, status: TargetUnsafe}
	if github == nodeUnsafe || workflows == nodeUnsafe {
		return target
	}
	snapshot, err := pathsafety.CaptureFile(fs, path)
	if err != nil {
		return target
	}
	target.snapshot = snapshot
	if snapshot.Exists {
		target.status = TargetExists
	} else {
		target.status = TargetAbsentSafe
	}
	return target
}

// Create performs one create-only mutation using exact server-held preview
// bytes. It never retries, removes, replaces, overwrites, or rolls back.
func (s *Service) Create(ctx context.Context, plan Plan, content []byte) Result {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return Result{Status: StatusPreMutationCanceled, Reason: ReasonCanceled}
	}
	if s == nil || s.FS == nil || plan.root == "" || !plan.rootSnap.Exists || plan.rootSnap.Kind != pathsafety.Directory {
		return Result{Status: StatusPreMutationStale, Reason: ReasonInvalidPlan}
	}
	if !validContent(content) {
		return Result{Status: StatusPreMutationStale, Reason: ReasonInvalidContent}
	}
	if plan.target.status == TargetExists {
		return Result{Status: StatusPreMutationStale, Reason: ReasonTargetExists}
	}
	if plan.target.status != TargetAbsentSafe {
		return Result{Status: StatusPreMutationStale, Reason: ReasonUnsafe}
	}
	if !plan.Valid() {
		return Result{Status: StatusPreMutationStale, Reason: ReasonInvalidPlan}
	}
	if !s.revalidatePlan(plan) {
		return Result{Status: StatusPreMutationStale, Reason: ReasonStale}
	}
	if err := ctx.Err(); err != nil {
		return Result{Status: StatusPreMutationCanceled, Reason: ReasonCanceled}
	}

	mutationStarted := false
	startMutation := func() { mutationStarted = true }
	// Keep the identities of directories actually used, including directories
	// created by this invocation. These become the receipt's post-write guards.
	rootSnap := plan.rootSnap
	githubSnap, ok, result := s.ensureDirectory(ctx, plan.github, rootSnap, startMutation, mutationStarted)
	if result.Status != "" {
		return result
	}
	if ok {
		// A fresh identity is mandatory after creation and for every existing
		// directory before it can become a parent for the next component.
		plan.github.snapshot = githubSnap
	}
	if err := ctx.Err(); err != nil && !mutationStarted {
		return Result{Status: StatusPreMutationCanceled, Reason: ReasonCanceled}
	}
	workflowsSnap, _, result := s.ensureDirectory(ctx, plan.workflows, githubSnap, startMutation, mutationStarted)
	if result.Status != "" {
		return result
	}
	if workflowsSnap.Exists {
		plan.workflows.snapshot = workflowsSnap
	}

	// This is the final parent/root guard. No slow Dashboard-controlled
	// operation occurs between this guard and CreateExclusive.
	if !s.finalParentGuard(plan.root, rootSnap, workflowsSnap) {
		if mutationStarted {
			return s.failedResult(ReasonParentDrift, content, plan, "", "")
		}
		return Result{Status: StatusPreMutationStale, Reason: ReasonParentDrift}
	}
	if err := ctx.Err(); err != nil && !mutationStarted {
		return Result{Status: StatusPreMutationCanceled, Reason: ReasonCanceled}
	}
	startMutation()
	handle, err := s.FS.CreateExclusive(plan.target.path, fileMode)
	if err != nil || handle == nil {
		return s.failedResult(ReasonCreate, content, plan, "", "")
	}
	return s.writeAndVerifyHandle(handle, plan, content, rootSnap, workflowsSnap)
}

// Execute is an alias for Create for HTTP layers that use execute terminology.
func (s *Service) Execute(ctx context.Context, plan Plan, content []byte) Result {
	return s.Create(ctx, plan, content)
}

func (s *Service) ensureDirectory(ctx context.Context, dir directoryPlan, parent pathsafety.Snapshot, start func(), started bool) (pathsafety.Snapshot, bool, Result) {
	if dir.status == nodeUnsafe {
		if started {
			return pathsafety.Snapshot{}, false, Result{Status: StatusFailedUnverified, Reason: ReasonStale}
		}
		return pathsafety.Snapshot{}, false, Result{Status: StatusPreMutationStale, Reason: ReasonStale}
	}
	if dir.status == nodePresent {
		got, err := pathsafety.CaptureDirectory(s.FS, dir.path)
		if err != nil || !got.Equal(dir.snapshot) || !within(parent.Path, got.Path) {
			if started {
				return pathsafety.Snapshot{}, false, Result{Status: StatusFailedUnverified, Reason: ReasonStale}
			}
			return pathsafety.Snapshot{}, false, Result{Status: StatusPreMutationStale, Reason: ReasonStale}
		}
		return got, true, Result{}
	}
	if err := ctx.Err(); err != nil && !started {
		return pathsafety.Snapshot{}, false, Result{Status: StatusPreMutationCanceled, Reason: ReasonCanceled}
	}
	// Revalidate the parent identity immediately before each one-component
	// directory mutation.
	latestParent, err := pathsafety.CaptureDirectory(s.FS, parent.Path)
	if err != nil || !latestParent.Equal(parent) || !within(latestParent.Path, dir.path) {
		if started {
			return pathsafety.Snapshot{}, false, Result{Status: StatusFailedUnverified, Reason: ReasonParentDrift}
		}
		return pathsafety.Snapshot{}, false, Result{Status: StatusPreMutationStale, Reason: ReasonParentDrift}
	}
	if err := ctx.Err(); err != nil && !started {
		return pathsafety.Snapshot{}, false, Result{Status: StatusPreMutationCanceled, Reason: ReasonCanceled}
	}
	start()
	if err := s.FS.Mkdir(dir.path, directoryMode); err != nil {
		return pathsafety.Snapshot{}, false, Result{Status: StatusFailedUnverified, Reason: ReasonDirectoryCreate}
	}
	created, err := pathsafety.CaptureDirectory(s.FS, dir.path)
	if err != nil || !created.Exists || !within(parent.Path, created.Path) {
		return pathsafety.Snapshot{}, false, Result{Status: StatusFailedUnverified, Reason: ReasonDirectoryCreate}
	}
	return created, true, Result{}
}

func (s *Service) finalParentGuard(root string, expectedRoot, expectedParent pathsafety.Snapshot) bool {
	latestRoot, err := pathsafety.CaptureDirectory(s.FS, root)
	if err != nil || !latestRoot.Equal(expectedRoot) {
		return false
	}
	latestParent, err := pathsafety.CaptureDirectory(s.FS, expectedParent.Path)
	if err != nil || !latestParent.Equal(expectedParent) || !within(latestRoot.Path, latestParent.Path) {
		return false
	}
	return true
}

func (s *Service) writeAndVerifyHandle(handle File, plan Plan, content []byte, rootSnap, parentSnap pathsafety.Snapshot) Result {
	// The handle is closed exactly once on every path. We collect all operation
	// failures, then perform readback even after a write/sync/close failure so a
	// complete file can be truthfully classified as verified-created + warning.
	var writeErr, syncErr, statErr, identityErr, closeErr error
	var statInfo os.FileInfo
	offset := 0
	for offset < len(content) {
		n, err := handle.Write(content[offset:])
		if n < 0 || n > len(content)-offset {
			writeErr = errors.New("invalid write progress")
			break
		}
		if n == 0 {
			if err == nil {
				writeErr = errZeroProgress
			} else {
				writeErr = err
			}
			break
		}
		offset += n
		if err != nil {
			writeErr = err
			break
		}
	}
	if err := handle.Sync(); err != nil {
		syncErr = err
	}
	statInfo, statCallErr := handle.Stat()
	if statCallErr != nil {
		statErr = statCallErr
	} else if statInfo.IsDir() || !statInfo.Mode().IsRegular() || statInfo.Size() != int64(offset) {
		statErr = errors.New("created handle is not the expected regular file")
	}
	fileIdentity, handleIdentityErr := handle.Identity()
	if handleIdentityErr != nil || strings.TrimSpace(fileIdentity) == "" {
		identityErr = handleIdentityErr
		if identityErr == nil {
			identityErr = errors.New("empty handle identity")
		}
	}
	closeErr = handle.Close()

	receipt := &Receipt{rootPath: plan.root, parentPath: parentSnap.Path, targetPath: plan.target.path, rootIdentity: rootSnap.FileIdentity, parentIdentity: parentSnap.FileIdentity, fileIdentity: fileIdentity, content: append([]byte(nil), content...), digest: digest(content)}
	verified := s.verifyReceipt(*receipt)
	if verified.Status == StatusVerifiedCreated {
		if writeErr != nil {
			verified.Warning, verified.Reason = WarningWrite, ReasonWrite
		} else if syncErr != nil {
			verified.Warning, verified.Reason = WarningSync, ReasonSync
		} else if statErr != nil {
			verified.Warning, verified.Reason = WarningStat, ReasonHandleStat
		} else if identityErr != nil {
			verified.Warning, verified.Reason = WarningIdentity, ReasonHandleIdentity
		} else if closeErr != nil {
			verified.Warning, verified.Reason = WarningClose, ReasonClose
		}
		verified.Receipt = receipt
		return verified
	}
	if writeErr != nil {
		if errors.Is(writeErr, errZeroProgress) {
			return Result{Status: StatusFailedUnverified, Reason: ReasonZeroProgress, Receipt: receipt}
		}
		return Result{Status: StatusFailedUnverified, Reason: ReasonWrite, Receipt: receipt}
	}
	if syncErr != nil {
		return Result{Status: StatusFailedUnverified, Reason: ReasonSync, Receipt: receipt}
	}
	if statErr != nil {
		return Result{Status: StatusFailedUnverified, Reason: ReasonHandleStat, Receipt: receipt}
	}
	if identityErr != nil {
		return Result{Status: StatusFailedUnverified, Reason: ReasonHandleIdentity, Receipt: receipt}
	}
	if closeErr != nil {
		return Result{Status: StatusFailedUnverified, Reason: ReasonClose, Receipt: receipt}
	}
	verified.Receipt = receipt
	return verified
}

func (s *Service) failedResult(reason ReasonCode, content []byte, plan Plan, rootID, parentID string) Result {
	return Result{Status: StatusFailedUnverified, Reason: reason, Receipt: &Receipt{rootPath: plan.root, parentPath: plan.workflows.path, targetPath: plan.target.path, rootIdentity: rootID, parentIdentity: parentID, content: append([]byte(nil), content...), digest: digest(content)}}
}

// VerifyCreated is the second, independently callable stable verification
// method. Callers may run slow read-only Git inspection before invoking it;
// it performs no process or mutation operation.
func (s *Service) VerifyCreated(ctx context.Context, receipt Receipt) Result {
	if ctx == nil {
		ctx = context.Background()
	}
	// Once a create has happened, cancellation must not suppress verification.
	return s.verifyReceipt(receipt)
}

func (s *Service) verifyReceipt(receipt Receipt) Result {
	if s == nil || s.FS == nil || receipt.rootPath == "" || receipt.parentPath == "" || receipt.targetPath == "" || len(receipt.content) == 0 || receipt.digest == "" || receipt.fileIdentity == "" {
		return Result{Status: StatusFailedUnverified, Reason: ReasonInvalidPlan}
	}
	root, err := pathsafety.CaptureDirectory(s.FS, receipt.rootPath)
	if err != nil || root.FileIdentity != receipt.rootIdentity {
		return Result{Status: StatusFailedUnverified, Reason: ReasonRepositoryDrift}
	}
	parent, err := pathsafety.CaptureDirectory(s.FS, receipt.parentPath)
	if err != nil || parent.FileIdentity != receipt.parentIdentity || !within(root.Path, parent.Path) {
		return Result{Status: StatusFailedUnverified, Reason: ReasonParentDrift}
	}
	readback, snapshot, err := pathsafety.ReadStableFile(s.FS, receipt.targetPath, MaxBytes)
	if err != nil {
		return Result{Status: StatusFailedUnverified, Reason: ReasonReadback}
	}
	if snapshot.FileIdentity != receipt.fileIdentity {
		return Result{Status: StatusFailedUnverified, Reason: ReasonReadbackReplacement}
	}
	if !bytes.Equal(readback, receipt.content) || digest(readback) != receipt.digest {
		return Result{Status: StatusFailedUnverified, Reason: ReasonReadbackMismatch}
	}
	if snapshot.AncestorIdentity != parent.FileIdentity || !within(root.Path, snapshot.AncestorPath) || snapshot.Path != receipt.targetPath {
		return Result{Status: StatusFailedUnverified, Reason: ReasonParentDrift}
	}
	return Result{Status: StatusVerifiedCreated, Receipt: &receipt}
}

func (s *Service) revalidatePlan(plan Plan) bool {
	current, err := s.Plan(context.Background(), plan.root)
	if err != nil || current.target.status != TargetAbsentSafe || current.rootSnap.FileIdentity != plan.rootSnap.FileIdentity || !current.rootSnap.Equal(plan.rootSnap) {
		return false
	}
	if !sameDirectoryPlan(current.github, plan.github) || !sameDirectoryPlan(current.workflows, plan.workflows) {
		return false
	}
	return current.target.status == plan.target.status && current.target.snapshot.Equal(plan.target.snapshot)
}

func sameDirectoryPlan(left, right directoryPlan) bool {
	if left.path != right.path || left.status != right.status {
		return false
	}
	if left.status == nodeUnsafe {
		return false
	}
	return left.snapshot.Equal(right.snapshot)
}

func validContent(content []byte) bool {
	if len(content) == 0 || int64(len(content)) > MaxBytes || !utf8.Valid(content) {
		return false
	}
	for _, r := range string(content) {
		if (r < 0x20 && r != '\t' && r != '\n' && r != '\r') || (r >= 0x7f && r <= 0x9f) {
			return false
		}
	}
	return true
}

func digest(content []byte) string {
	hash := sha256.Sum256(content)
	return hex.EncodeToString(hash[:])
}

func within(parent, child string) bool {
	parent, child = filepath.Clean(parent), filepath.Clean(child)
	if strings.EqualFold(parent, child) {
		return true
	}
	if !strings.EqualFold(filepath.VolumeName(parent), filepath.VolumeName(child)) {
		return false
	}
	rel, err := filepath.Rel(parent, child)
	if err != nil {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel)
}
